#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = $ARGV[0] // die "usage: $0 <repo-root>\n";
my $MODULE = 'github.com/usememos/memos';

# --- Parse a Go file into structured data ---
sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    my @lines = map { chomp; $_ } <$fh>;
    close $fh;

    my $pkg = '';
    for (@lines) {
        if (/^package\s+(\w+)/) { $pkg = $1; last; }
    }
    return undef unless $pkg;

    # imports: alias_or_name -> full import path
    my %imports;
    my $in_import = 0;
    my $import_paren = 0;
    for my $line (@lines) {
        if ($line =~ /^import\s+\(\s*$/) { $in_import = 1; $import_paren = 1; next; }
        if ($line =~ /^import\s+"([^"]+)"/) {
            my $p = $1;
            (my $def = $p) =~ s|.*/||;
            $imports{$def} = $p;
            next;
        }
        if ($in_import) {
            if ($line =~ /^\s*"([^"]+)"/) {
                my $p = $1;
                (my $def = $p) =~ s|.*/||;
                $imports{$def} = $p;
            } elsif ($line =~ /^\s+(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            }
            if ($line =~ /\)/) { $in_import = 0; }
        }
    }

    # reverse: full path -> set of local names (default + aliases)
    my %path_to_names;
    for my $name (keys %imports) {
        push @{ $path_to_names{ $imports{$name} } }, $name;
    }

    # functions with body line ranges via brace matching
    my @funcs;
    for (my $i = 0; $i < @lines; $i++) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/;
        my $name = $1;
        my $recv = '';
        if ($line =~ /^func\s+\(([^)]*)\)/) {
            $recv = $1;
            $recv =~ s/^\*//;
            $recv =~ s/^\w+\s+//;
            $recv =~ s/\s+$//;
        }
        my $start = $i + 1;
        my $brace = 0;
        my $found = 0;
        my $end = $start;
        for (my $j = $i; $j < @lines; $j++) {
            my $l = $lines[$j];
            for my $c (split //, $l) {
                if ($c eq '{') { $brace++; $found = 1; }
                elsif ($c eq '}') { $brace--; }
            }
            if ($found && $brace == 0) {
                $end = $j + 1;
                last;
            }
        }
        push @funcs, {
            name  => $name,
            recv  => $recv,
            start => $start,
            end   => $end,
            id    => "$path#$start",
        };
    }

    return {
        path    => $path,
        pkg     => $pkg,
        lines   => \@lines,
        imports => \%imports,
        path_to_names => \%path_to_names,
        funcs   => \@funcs,
    };
}

# import path -> filesystem dir under module
sub import_to_dir {
    my ($imp) = @_;
    return undef unless $imp =~ /^\Q$MODULE\E(?:\/(.*))?$/;
    my $rel = $1 // '';
    return "$ROOT/$rel";
}

# Is declaration under internal/?
sub is_internal_decl {
    my ($path) = @_;
    return $path =~ m{^\Q$ROOT\E/internal/};
}

# Build target key for internal symbol
sub target_key {
    my ($path, $pkg, $name, $recv) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$ROOT\E\/?//;
    if ($recv) {
        return "$rel|$pkg|($recv).$name";
    }
    return "$rel|$pkg|$name";
}

# Collect all internal targets
my %targets;      # key -> { path, pkg, name, recv, import_path }
my %file_data;    # path -> parsed

find({
    wanted => sub {
        return unless /\.go$/;
        my $path = $File::Find::name;
        my $data = parse_go_file($path);
        return unless $data;
        $file_data{$path} = $data;
        next unless is_internal_decl($path);

        my $rel = $path;
        $rel =~ s/^\Q$ROOT\E\/?//;
        # derive import path from file location
        my $dir = dirname($rel);
        my $import_path = $MODULE . ($dir eq '.' ? '' : "/$dir");

        for my $f (@{ $data->{funcs} }) {
            next if $f->{name} eq 'init';
            my $key = target_key($path, $data->{pkg}, $f->{name}, $f->{recv});
            $targets{$key} = {
                key         => $key,
                path        => $path,
                rel         => $rel,
                pkg         => $data->{pkg},
                name        => $f->{name},
                recv        => $f->{recv},
                import_path => $import_path,
            };
        }
    },
    no_chdir => 1,
}, $ROOT);

# Map import_path -> target keys in that package
my %import_path_targets;
for my $t (values %targets) {
    push @{ $import_path_targets{ $t->{import_path} } }, $t->{key};
}

# Strip comments from line (rough)
sub strip_comments {
    my ($s) = @_;
    $s =~ s/\/\/.*$//;
    $s =~ s/\/\*.*?\*\///g;
    return $s;
}

# Detect if identifier is a type/context keyword false positive
my %not_call = map { $_ => 1 } qw(if for switch return go defer select case default else range map chan struct interface func type var const import package);

# Analyze calls in each caller function
my %fanin;  # target_key -> { callers => { caller_id => 1 } }

for my $caller_path (sort keys %file_data) {
    my $data = $file_data{$caller_path};
    my $caller_pkg = $data->{pkg};
    my $lines = $data->{lines};

    for my $caller (@{ $data->{funcs} }) {
        next if $caller->{name} eq 'init';
        my $caller_id = "$caller_path#$caller->{start}|$caller_pkg|"
            . ($caller->{recv} ? "($caller->{recv})." : '') . $caller->{name};

        for (my $i = $caller->{start}; $i < $caller->{end}; $i++) {
            my $line = strip_comments($lines->[$i - 1]);
            next if $line =~ /^\s*func\s+/;  # nested func decl

            # Qualified calls: alias.FuncName( or pkg.FuncName(
            while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
                my ($qual, $fname) = ($1, $2);
                next if $not_call{$qual};

                # Same-package qualified (rare): pkg.Func
                if ($qual eq $caller_pkg && is_internal_decl($caller_path)) {
                    my $key = target_key($caller_path, $caller_pkg, $fname, '');
                    # also try methods - skip for package-level
                    if ($targets{$key}) {
                        $fanin{$key}{callers}{$caller_id} = 1;
                    }
                }

                # Import resolution
                my $imp = $data->{imports}{$qual};
                if ($imp) {
                    for my $tk (@{ $import_path_targets{$imp} // [] }) {
                        my $t = $targets{$tk};
                        next unless $t;
                        next unless $t->{name} eq $fname && !$t->{recv};
                        $fanin{$tk}{callers}{$caller_id} = 1;
                    }
                }
            }

            # Unqualified calls within same package
            if (is_internal_decl($caller_path)) {
                while ($line =~ /\b([A-Za-z_]\w*)\s*\(/g) {
                    my $fname = $1;
                    next if $not_call{$fname};
                    next if $fname eq $caller->{name};  # might be recursion - still valid caller is self? skip self-recursion counting as distinct caller - actually same caller
                    # skip if preceded by '.' (already handled)
                    my $pos = pos($line) - length($fname) - 1;
                    next if $pos > 0 && substr($line, $pos - 1, 1) eq '.';

                    my $key = target_key($caller_path, $caller_pkg, $fname, '');
                    if ($targets{$key}) {
                        $fanin{$key}{callers}{$caller_id} = 1;
                    }
                }
            }

            # Method calls: .MethodName(
            while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
                my $mname = $1;
                # If caller is in same internal package, check local methods
                if (is_internal_decl($caller_path)) {
                    for my $tk (keys %targets) {
                        my $t = $targets{$tk};
                        next unless $t->{name} eq $mname && $t->{recv};
                        next unless $t->{import_path} eq ($MODULE . '/' . dirname($data->{path} =~ s/^\Q$ROOT\E\/?//r));
                        # same file package only for unqualified method - weak heuristic
                    }
                }
                # Cross-package method calls via known receiver types are hard without types.
                # Handle explicit Type.method only via qualified type patterns below.
            }

            # Cross-package method via imported package: can't know receiver type easily.
            # Handle (*Type).Method pattern in same file - skip.

            # For cross-package methods where code uses imported pkg and method on returned type:
            # Pattern: we can't reliably detect x.Method without types.
        }

        # Second pass for cross-package method calls using import aliases + method name
        # When file imports internal/X and calls something.Method where something is local var,
        # we miss it. Complement with global search per target later.
    }
}

# --- Global complementary pass for cross-package method and missed calls ---
# For each internal target, scan all files for call patterns.

for my $tk (sort keys %targets) {
    my $t = $targets{$tk};
    my $fname = $t->{name};
    my $imp = $t->{import_path};
    my @local_names = @{ $file_data{ $t->{path} }{path_to_names}{$imp} // [] };
    # default package name from path
    (my $defpkg = $imp) =~ s|.*/||;
    push @local_names, $defpkg unless grep { $_ eq $defpkg } @local_names;
    @local_names = uniq(@local_names);

    for my $fpath (sort keys %file_data) {
        my $data = $file_data{$fpath};
        my $lines = $data->{lines};

        # names this file can use for the import
        my @names;
        for my $n (keys %{ $data->{imports} }) {
            push @names, $n if $data->{imports}{$n} eq $imp;
        }
        push @names, $defpkg if exists $data->{imports}{$defpkg} || grep { $data->{imports}{$_} eq $imp } keys %{ $data->{imports} };
        @names = uniq(@names);

        for my $caller (@{ $data->{funcs} }) {
            next if $caller->{name} eq 'init';
            my $caller_id = "$fpath#$caller->{start}|$data->{pkg}|"
                . ($caller->{recv} ? "($caller->{recv})." : '') . $caller->{name};

            for (my $i = $caller->{start}; $i < $caller->{end}; $i++) {
                my $line = strip_comments($lines->[$i - 1]);

                if (!$t->{recv}) {
                    # package-level function
                    for my $n (@names) {
                        if ($line =~ /\b\Q$n\E\.\Q$fname\E\s*\(/) {
                            $fanin{$tk}{callers}{$caller_id} = 1;
                        }
                    }
