#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $ROOT = $ARGV[0] // die "usage: $0 <repo-root>\n";
my $MODULE = 'github.com/usememos/memos';

# --- Parse a Go file into structured data ---
sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    my @lines = map { chomp; $_ } <$fh>;
    close $fh;

    my $pkg = '';
    for (@lines) {
        if (/^package\s+(\w+)/) { $pkg = $1; last; }
    }
    return undef unless $pkg;

    # imports: alias_or_name -> full import path
    my %imports;
    my $in_import = 0;
    my $import_paren = 0;
    for my $line (@lines) {
        if ($line =~ /^import\s+\(\s*$/) { $in_import = 1; $import_paren = 1; next; }
        if ($line =~ /^import\s+"([^"]+)"/) {
            my $p = $1;
            (my $def = $p) =~ s|.*/||;
            $imports{$def} = $p;
            next;
        }
        if ($in_import) {
            if ($line =~ /^\s*"([^"]+)"/) {
                my $p = $1;
                (my $def = $p) =~ s|.*/||;
                $imports{$def} = $p;
            } elsif ($line =~ /^\s+(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            }
            if ($line =~ /\)/) { $in_import = 0; }
        }
    }

    # reverse: full path -> set of local names (default + aliases)
    my %path_to_names;
    for my $name (keys %imports) {
        push @{ $path_to_names{ $imports{$name} } }, $name;
    }

    # functions with body line ranges via brace matching
    my @funcs;
    for (my $i = 0; $i < @lines; $i++) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/;
        my $name = $1;
        my $recv = '';
        if ($line =~ /^func\s+\(([^)]*)\)/) {
            $recv = $1;
            $recv =~ s/^\*//;
            $recv =~ s/^\w+\s+//;
            $recv =~ s/\s+$//;
        }
        my $start = $i + 1;
        my $brace = 0;
        my $found = 0;
        my $end = $start;
        for (my $j = $i; $j < @lines; $j++) {
            my $l = $lines[$j];
            for my $c (split //, $l) {
                if ($c eq '{') { $brace++; $found = 1; }
                elsif ($c eq '}') { $brace--; }
            }
            if ($found && $brace == 0) {
                $end = $j + 1;
                last;
            }
        }
        push @funcs, {
            name  => $name,
            recv  => $recv,
            start => $start,
            end   => $end,
            id    => "$path#$start",
        };
    }

    return {
        path    => $path,
        pkg     => $pkg,
        lines   => \@lines,
        imports => \%imports,
        path_to_names => \%path_to_names,
        funcs   => \@funcs,
    };
}

