+    my $ca = scalar keys %{ $fanin{$a}{callers} // {} };
+    my $cb = scalar keys %{ $fanin{$b}{callers} // {} };
+    $cb <=> $ca || $a cmp $b;
+} keys %targets;
+
+print "TOP 25 BY DISTINCT CALLER COUNT\n";
+print "=" x 80, "\n";
+my $n = 0;
+for my $tk (@ranked) {
+    last if ++$n > 25;
+    my $t = $targets{$tk};
+    my $count = scalar keys %{ $fanin{$tk}{callers} // {} };
+    my $sym = $t->{recv} ? "($t->{recv}).$t->{name}" : $t->{name};
+    print sprintf("%3d  %4d callers  %s  [%s]\n", $n, $count, $sym, $t->{rel});
+}
+
