+    print "\n#$n $sym @ $t->{rel} ($count callers)\n";
+    my $c = 0;
+    for my $cid (sort keys %{ $fanin{$tk}{callers} // {} }) {
+        print "  - $cid\n" if ++$c <= 15;
+    }
+    print "  ... and ", $count - 15, " more\n" if $count > 15;
