#!/usr/bin/perl
use strict;
use warnings;

my $ROOT = $ARGV[0] // die "usage: $0 <repo-root>\n";
chomp(my @all_go = `find '$ROOT' -name '*.go' ! -path '*/vendor/*' 2>/dev/null`);
my $MODULE = 'github.com/usememos/memos';

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    my @lines = map { chomp; $_ } <$fh>;
    close $fh;

    my $pkg = '';
    for (@lines) {
        if (/^package\s+(\w+)/) { $pkg = $1; last; }
    }
    return undef unless $pkg;

    my %imports;
    my $in_import = 0;
    for my $line (@lines) {
        if ($line =~ /^import\s+\(\s*$/) { $in_import = 1; next; }
        if ($line =~ /^import\s+"([^"]+)"/) {
            my $p = $1;
            (my $def = $p) =~ s|.*/||;
            $imports{$def} = $p;
            next;
        }
        if ($in_import) {
            if ($line =~ /^\s*"([^"]+)"/) {
                my $p = $1;
                (my $def = $p) =~ s|.*/||;
                $imports{$def} = $p;
            } elsif ($line =~ /^\s+(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            }
            if ($line =~ /\)/) { $in_import = 0; }
        }
    }

    my %path_to_names;
    for my $name (keys %imports) {
        push @{ $path_to_names{ $imports{$name} } }, $name;
    }

    my @funcs;
    for (my $i = 0; $i < @lines; $i++) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/;
        my $name = $1;
        my $recv = '';
        if ($line =~ /^func\s+\(([^)]*)\)/) {
            $recv = $1;
            $recv =~ s/^\*?(\w+)\s+//;
            $recv =~ s/^\*//;
        }
        my $start = $i + 1;
        my $brace = 0;
        my $found = 0;
        my $end = $start;
        for (my $j = $i; $j < @lines; $j++) {
            for my $c (split //, $lines[$j]) {
                if ($c eq '{') { $brace++; $found = 1; }
                elsif ($c eq '}') { $brace--; }
            }
            if ($found && $brace == 0) {
                $end = $j + 1;
                last;
            }
        }
        push @funcs, { name => $name, recv => $recv, start => $start, end => $end };
    }

    return { path => $path, pkg => $pkg, lines => \@lines, imports => \%imports, path_to_names => \%path_to_names, funcs => \@funcs };
}

sub file_dir {
    my ($path) = @_;
    $path =~ s/\/[^\/]+$//;
    return $path;
}

sub import_path_for_file {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$ROOT\E\/?//;
    $rel =~ s/\/[^\/]+$//;
    return $MODULE . ($rel ? "/$rel" : '');
}

sub is_internal {
    my ($path) = @_;
    return $path =~ m{^\Q$ROOT\E/internal/};
}

sub target_key {
    my ($path, $pkg, $name, $recv) = @_;
    my $rel = $path; $rel =~ s/^\Q$ROOT\E\/?//;
    return $recv ? "$rel|$pkg|($recv).$name" : "$rel|$pkg|$name";
}

my %targets;
my %file_data;

for my $path (@all_go) {
    my $data = parse_go_file($path);
    next unless $data;
    $file_data{$path} = $data;
    next unless is_internal($path);

    my $import_path = import_path_for_file($path);
    for my $f (@{ $data->{funcs} }) {
        next if $f->{name} eq 'init';
        my $key = target_key($path, $data->{pkg}, $f->{name}, $f->{recv});
        $targets{$key} = {
            path => $path, pkg => $data->{pkg}, name => $f->{name},
            recv => $f->{recv}, import_path => $import_path,
            rel => do { my $r=$path; $r=~s/^\Q$ROOT\E\/?//; $r },
        };
    }
}

my %import_path_targets;
for my $t (values %targets) {
    push @{ $import_path_targets{ $t->{import_path} } }, target_key($t->{path}, $t->{pkg}, $t->{name}, $t->{recv});
}

sub strip_comments {
    my ($s) = @_;
    $s =~ s/\/\/.*$//;
    return $s;
}

my %kw = map { $_ => 1 } qw(if for switch return go defer select case default else range map chan struct interface func type var const import package);

my %fanin;

for my $fpath (keys %file_data) {
    my $data = $file_data{$fpath};
    my $lines = $data->{lines};
    my $fdir = file_dir($fpath);

    for my $caller (@{ $data->{funcs} }) {
        next if $caller->{name} eq 'init';
        my $caller_id = "$fpath:$caller->{start}|$data->{pkg}|"
            . ($caller->{recv} ? "($caller->{recv})." : '') . $caller->{name};

        for (my $i = $caller->{start}; $i < $caller->{end}; $i++) {
            my $line = strip_comments($lines->[$i - 1]);

            for my $tk (keys %targets) {
                my $t = $targets{$tk};
                my $fname = $t->{name};
                my $imp = $t->{import_path};
                my $tdir = file_dir($t->{path});

                my @aliases;
                for my $n (keys %{ $data->{imports} }) {
                    push @aliases, $n if $data->{imports}{$n} eq $imp;
                }
                (my $defpkg = $imp) =~ s|.*/||;
                push @aliases, $defpkg if (keys %{ $data->{imports} }) == 0 && $data->{pkg} eq $t->{pkg} && $fdir eq $tdir;

                if (!$t->{recv}) {
                    for my $a (@aliases) {
                        if ($line =~ /\b\Q$a\E\.\Q$fname\E\s*\(/) {
                            $fanin{$tk}{$caller_id} = 1;
                        }
                    }
                    if ($data->{pkg} eq $t->{pkg} && $fdir eq $tdir) {
                        if ($line =~ /(?<![.\w])\Q$fname\E\s*\(/ && !$kw{$fname}) {
                            $fanin{$tk}{$caller_id} = 1;
                        }
                    }
                } else {
                    if ($data->{pkg} eq $t->{pkg} && $fdir eq $tdir) {
                        if ($line =~ /\.\Q$fname\E\s*\(/ || $line =~ /(?<![.\w])\Q$fname\E\s*\(/) {
                            $fanin{$tk}{$caller_id} = 1;
                        }
                    } elsif (@aliases) {
                        if ($line =~ /\.\Q$fname\E\s*\(/) {
                            $fanin{$tk}{$caller_id} = 1;
                        }
                    }
                }
            }
        }
    }
}

my @ranked = sort {
    (scalar keys %{ $fanin{$b} // {} }) <=> scalar keys %{ $fanin{$a} // {} })
        || ($a cmp $b)
} keys %targets;

print "TOP 30 DISTINCT CALLER FAN-IN (internal/ declarations)\n";
print "=" x 90, "\n";
my $rank = 0;
for my $tk (@ranked) {
    last if ++$rank > 30;
    my $t = $targets{$tk};
    my $c = scalar keys %{ $fanin{$tk} // {} };
    my $sym = $t->{recv} ? "($t->{recv}).$t->{name}" : $t->{name};
    printf "%2d. %4d  %-45s  %s\n", $rank, $c, $sym, $t->{rel};
}

for my $detail_n (1..5) {
    my $tk = $ranked[$detail_n - 1];
    my $t = $targets{$tk};
    my @callers = sort keys %{ $fanin{$tk} // {} };
    my $sym = $t->{recv} ? "($t->{recv}).$t->{name}" : $t->{name};
    print "\n--- #$detail_n $sym ($t->{rel}) — ", scalar(@callers), " callers ---\n";
    my $i = 0;
    for (@callers) { print "  $_\n" if ++$i <= 20; }
    print "  ... (+", scalar(@callers) - 20, " more)\n" if @callers > 20;
}

print "\nTotal internal declared funcs/methods (excl init): ", scalar keys %targets, "\n";

