#!/usr/bin/perl
use strict;
use warnings;

my $ROOT = $ARGV[0] // die "usage: $0 <repo-root>\n";
chomp(my @all_go = `find '$ROOT' -name '*.go' ! -path '*/vendor/*' 2>/dev/null`);
my $MODULE = 'github.com/usememos/memos';

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    my @lines = map { chomp; $_ } <$fh>;
    close $fh;
    my $pkg = '';
    for (@lines) { if (/^package\s+(\w+)/) { $pkg = $1; last; } }
    return undef unless $pkg;

    my %imports; my $in_import = 0;
    for my $line (@lines) {
        if ($line =~ /^import\s+\(\s*$/) { $in_import = 1; next; }
        if ($line =~ /^import\s+"([^"]+)"/) { my $p=$1; (my $d=$p)=~s|.*/||; $imports{$d}=$p; next; }
        if ($in_import) {
            if ($line =~ /^\s*"([^"]+)"/) { my $p=$1; (my $d=$p)=~s|.*/||; $imports{$d}=$p; }
            elsif ($line =~ /^\s+(\w+)\s+"([^"]+)"/) { $imports{$1}=$2; }
            if ($line =~ /\)/) { $in_import = 0; }
        }
    }

    my @funcs;
    for (my $i=0; $i<@lines; $i++) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/;
        my ($name, $recv) = ($1, '');
        if ($line =~ /^func\s+\(([^)]*)\)/) {
            $recv = $1; $recv =~ s/^\*?(\w+)\s+//; $recv =~ s/^\*//;
        }
        my ($start, $brace, $found, $end) = ($i+1, 0, 0, $i+1);
        for (my $j=$i; $j<@lines; $j++) {
            for my $c (split //, $lines[$j]) {
                if ($c eq '{') { $brace++; $found=1; } elsif ($c eq '}') { $brace--; }
            }
            if ($found && $brace==0) { $end = $j+1; last; }
        }
        push @funcs, { name=>$name, recv=>$recv, start=>$start, end=>$end };
    }
    return { path=>$path, pkg=>$pkg, is_test=>($path=~/\_test\.go$/), lines=>\@lines, imports=>\%imports, funcs=>\@funcs };
}

sub file_dir { my ($p)=@_; $p=~s/\/[^\/]+$//; $p }
sub is_internal { $_[0] =~ m{^\Q$ROOT\E/internal/} }
sub import_path_for_file {
    my ($path)=@_; my $rel=$path; $rel=~s/^\Q$ROOT\E\/?//; $rel=~s/\/[^\/]+$//;
    return $MODULE . ($rel ? "/$rel" : '');
}
sub target_key {
    my ($path,$pkg,$name,$recv)=@_;
    my $rel=$path; $rel=~s/^\Q$ROOT\E\/?//;
    return $recv ? "$rel|$pkg|($recv).$name" : "$rel|$pkg|$name";
}
sub strip_comments { my ($s)=@_; $s=~s/\/\/.*$//; $s }

my (%targets, %file_data);
for my $path (@all_go) {
    my $d = parse_go_file($path); next unless $d;
    $file_data{$path} = $d;
    next unless is_internal($path);
    my $imp = import_path_for_file($path);
    for my $f (@{$d->{funcs}}) {
        next if $f->{name} eq 'init';
        my $key = target_key($path,$d->{pkg},$f->{name},$f->{recv});
        $targets{$key} = { path=>$path, pkg=>$d->{pkg}, name=>$f->{name}, recv=>$f->{recv},
            import_path=>$imp, rel=>do{my $r=$path;$r=~s/^\Q$ROOT\E\/?//;$r} };
    }
}

my (%fanin_all, %fanin_prod);
my %kw = map {$_=>1} qw(if for switch return go defer select case default else range map chan struct interface func type var const import package);

for my $fpath (keys %file_data) {
    my $data = $file_data{$fpath};
    my ($lines, $fdir) = ($data->{lines}, file_dir($fpath));
    for my $caller (@{$data->{funcs}}) {
        next if $caller->{name} eq 'init';
        my $cid = "$fpath:$caller->{start}|$data->{pkg}|".($caller->{recv}? "($caller->{recv}).":'').$caller->{name};
        my $prod = !$data->{is_test};

        for (my $i=$caller->{start}; $i<$caller->{end}; $i++) {
            my $line = strip_comments($lines->[$i-1]);
            for my $tk (keys %targets) {
                my $t = $targets{$tk};
                my ($fname, $imp, $tdir) = ($t->{name}, $t->{import_path}, file_dir($t->{path}));
                my @aliases;
                for my $n (keys %{$data->{imports}}) { push @aliases, $n if $data->{imports}{$n} eq $imp; }
                my $matched = 0;
                if (!$t->{recv}) {
                    for my $a (@aliases) { if ($line =~ /\b\Q$a\E\.\Q$fname\E\s*\(/) { $matched=1; last; } }
                    if (!$matched && $data->{pkg} eq $t->{pkg} && $fdir eq $tdir) {
                        $matched=1 if $line =~ /(?<![.\w])\Q$fname\E\s*\(/ && !$kw{$fname};
                    }
                } else {
                    if ($data->{pkg} eq $t->{pkg} && $fdir eq $tdir) {
                        $matched=1 if $line =~ /\.\Q$fname\E\s*\(/ || $line =~ /(?<![.\w])\Q$fname\E\s*\(/;
                    } elsif (@aliases && $line =~ /\.\Q$fname\E\s*\(/) {
                        $matched=1;
                    }
                }
                if ($matched) {
                    $fanin_all{$tk}{$cid}=1;
                    $fanin_prod{$tk}{$cid}=1 if $prod;
                }
            }
        }
    }
}

sub print_rank {
    my ($title, $fanin_ref, $limit) = @_;
    print "\n$title\n", "=" x 90, "\n";
    my @ranked = sort { (scalar keys %{$fanin_ref->{$b}//{}}) <=> (scalar keys %{$fanin_ref->{$a}//{}}) || $a cmp $b } keys %targets;
    my $n=0;
    for my $tk (@ranked) {
        last if ++$n > $limit;
        my $t = $targets{$tk};
        my $c = scalar keys %{$fanin_ref->{$tk}//{}};
        my $sym = $t->{recv} ? "($t->{recv}).$t->{name}" : $t->{name};
        printf "%2d. %4d  %-45s  %s\n", $n, $c, $sym, $t->{rel};
    }
    return @ranked;
}

my @all_ranked = print_rank("ALL FILES (incl. tests)", \%fanin_all, 20);
my @prod_ranked = print_rank("PRODUCTION ONLY (exclude _test.go callers)", \%fanin_prod, 20);

print "\nPRODUCTION DETAIL TOP 8\n";
for my $i (0..7) {
    my $tk = $prod_ranked[$i]; next unless defined $tk;
    my $t = $targets{$tk}; my @c = sort keys %{$fanin_prod{$tk}//{}};
    my $sym = $t->{recv} ? "($t->{recv}).$t->{name}" : $t->{name};
    print "\n#".($i+1)." $sym @ $t->{rel} — ", scalar(@c), " prod callers\n";
    print "  $_\n" for @c;
}

print "\nTotal internal symbols: ", scalar keys %targets, "\n";

