+        next if $caller->{name} eq 'init';
+        my $caller_id = "$fpath:$caller->{start}|$data->{pkg}|"
+            . ($caller->{recv} ? "($caller->{recv})." : '') . $caller->{name};
+
+        for (my $i = $caller->{start}; $i < $caller->{end}; $i++) {
+            my $line = strip_comments($lines->[$i - 1]);
+            for my $tk (keys %targets) {
+                my $t = $targets{$tk};
+                my ($fname, $imp, $tdir) = ($t->{name}, $t->{import_path}, file_dir($t->{path}));
+                my @aliases;
+                for my $n (keys %{ $data->{imports} }) {
+                    push @aliases, $n if $data->{imports}{$n} eq $imp;
+                }
+                my $matched = 0;
+                if (!$t->{recv}) {
+                    for my $a (@aliases) {
+                        if ($line =~ /\b\Q$a\E\.\Q$fname\E\s*\(/) { $matched = 1; last; }
+                    }
+                    if (!$matched && $data->{pkg} eq $t->{pkg} && $fdir eq $tdir) {
+                        $matched = 1 if $line =~ /(?<![.\w])\Q$fname\E\s*\(/ && !$kw{$fname};
+                    }
+                } else {
+                    if ($data->{pkg} eq $t->{pkg} && $fdir eq $tdir) {
+                        $matched = 1 if $line =~ /\.\Q$fname\E\s*\(/ || $line =~ /(?<![.\w])\Q$fname\E\s*\(/;
+                    } elsif (@aliases && $line =~ /\.\Q$fname\E\s*\(/) {
+                        $matched = 1;
+                    }
+                }
+                if ($matched) {
+                    $fanin_all{$tk}{$caller_id} = 1;
+                    $fanin_prod{$tk}{$caller_id} = 1 if $caller_is_prod;
+                }
+            }
+        }
+    }
+}
+
+sub print_rank {
+    my ($title, $fanin_ref, $limit) = @_;
+    print "\n$title\n", "=" x 90, "\n";
+    my @ranked = sort {
+        (scalar keys %{ $fanin_ref->{$b} // {} }) <=> (scalar keys %{ $fanin_ref->{$a} // {} })
+            || ($a cmp $b)
+    } keys %targets;
+    my $n = 0;
+    for my $tk (@ranked) {
+        last if ++$n > $limit;
+        my $t = $targets{$tk};
+        my $c = scalar keys %{ $fanin_ref->{$tk} // {} };
+        next if $title =~ /PRODUCTION/ && $c == 0 && $n > 15;
+        my $sym = $t->{recv} ? "($t->{recv}).$t->{name}" : $t->{name};
+        printf "%2d. %4d  %-45s  %s\n", $n, $c, $sym, $t->{rel};
+    }
+    return @ranked;
+}
+
+my @all_ranked = print_rank("ALL FILES (incl. _test.go callers)", \%fanin_all, 25);
+my @prod_ranked = print_rank("PRODUCTION CALLERS ONLY (caller not in _test.go)", \%fanin_prod, 25);
+
+for my $i (0..4) {
+    my $tk = $all_ranked[$i]; next unless $tk;
+    my $t = $targets{$tk};
+    print "\n[ALL] #", $i+1, " ", ($t->{recv}? "($t->{recv}).":""), $t->{name}, " prod=", scalar(keys %{ $fanin_prod{$tk}//{} }), " total=", scalar(keys %{ $fanin_all{$tk}//{} }), "\n";
+    my $shown = 0;
+    for my $c (sort keys %{ $fanin_prod{$tk} // {} }) {
+        print "  P $c\n" if ++$shown <= 12;
+    }
+}
+
+print "\nTotal internal symbols analyzed: ", scalar keys %targets, "\n";

